diff --git a/solution.mjs b/solution.mjs
new file mode 100644
index 0000000..7c186e2
--- /dev/null
+++ b/solution.mjs
@@ -0,0 +1,9 @@
+export function intersection(a, b) {
+  const result = [];
+  for (const x of a) {
+    if (b.includes(x) && !result.includes(x)) {
+      result.push(x);
+    }
+  }
+  return result;
+}
